export class CoreChartError extends Error{constructor(code,message,details={}){super(message);this.name='CoreChartError';this.code=code;this.details=Object.freeze({...details});}}
const fail=(c,m,d={})=>{throw new CoreChartError(c,m,d)};const finite=v=>typeof v==='number'&&Number.isFinite(v);const freeze=x=>Object.freeze(x);
export const CORE_CHART_TYPES=freeze(['Vertical Bar','Horizontal Bar','Grouped Bar','Stacked Bar','100% Stacked Bar','Paired Before/After Bars','Dumbbell','Slope Chart','Waterfall','Line Chart','Multi-Line','Area Chart','Stacked Area','Sparkline','Step Chart','Scatter Plot','Regression Scatter','Bubble Plot','Histogram','Box Plot','Violin Plot','Strip / Dot Plot','ECDF','Pareto','Treemap','Donut','Pie','Funnel','Sankey']);
const categoryTypes=new Set(['Vertical Bar','Horizontal Bar','Grouped Bar','Stacked Bar','100% Stacked Bar','Paired Before/After Bars','Dumbbell','Slope Chart','Waterfall','Line Chart','Multi-Line','Area Chart','Stacked Area','Sparkline','Step Chart','Pareto','Donut','Pie','Funnel']);
const pointTypes=new Set(['Scatter Plot','Regression Scatter','Bubble Plot','Strip / Dot Plot']);
const distributionTypes=new Set(['Histogram','Box Plot','Violin Plot','ECDF']);
function number(v,label){v=+v;if(!finite(v))fail('CHART_NUMBER',`${label} must be finite`,{value:v});return v}
function categories(input){const cats=(input.categories??[]).map(String);if(!cats.length)fail('CHART_CATEGORIES','categories required');if(new Set(cats).size!==cats.length)fail('CHART_CATEGORIES','category labels must be unique');return cats}
function series(input,count){const list=input.series??(input.values?[{name:'Series',values:input.values}]:[]);if(!Array.isArray(list)||!list.length)fail('CHART_SERIES','at least one series required');return list.map((s,si)=>{if(!Array.isArray(s.values)||s.values.length!==count)fail('CHART_SERIES','series length must equal categories',{si,count});return freeze({name:String(s.name??`Series ${si+1}`),values:freeze(s.values.map((v,i)=>number(v,`series[${si}][${i}]`)))});});}
export function prepareCoreChart(type,input={}){if(!CORE_CHART_TYPES.includes(type))fail('CHART_TYPE','unknown chart type',{type});let data;
 if(categoryTypes.has(type)){const cats=categories(input),ss=series(input,cats.length);if(['100% Stacked Bar'].includes(type)){for(let i=0;i<cats.length;i++){const sum=ss.reduce((a,s)=>a+s.values[i],0);if(sum<=0)fail('CHART_NORMALIZE','100% stacked category totals must be positive',{i});}}
  if(['Pie','Donut','Funnel'].includes(type)&&ss.length!==1)fail('CHART_SERIES','chart requires exactly one series',{type});data=freeze({categories:freeze(cats),series:freeze(ss)});
 }else if(pointTypes.has(type)){if(!Array.isArray(input.points)||input.points.length<2)fail('CHART_POINTS','at least two points required');data=freeze({points:freeze(input.points.map((p,i)=>freeze({x:number(p.x,`point ${i} x`),y:number(p.y,`point ${i} y`),r:type==='Bubble Plot'?Math.max(0,number(p.r??1,`point ${i} r`)):undefined,label:String(p.label??'')}))) });
 }else if(distributionTypes.has(type)){if(!Array.isArray(input.values)||input.values.length<2)fail('CHART_VALUES','at least two values required');const vals=input.values.map((v,i)=>number(v,`value ${i}`));data=freeze({values:freeze(vals)});
 }else if(type==='Treemap'){if(!Array.isArray(input.nodes)||!input.nodes.length)fail('CHART_NODES','treemap nodes required');data=freeze({nodes:freeze(input.nodes.map((n,i)=>{const value=number(n.value,`node ${i}`);if(value<0)fail('CHART_VALUE','treemap values must be nonnegative');return freeze({id:String(n.id??i),label:String(n.label??n.id??i),value});}))});
 }else if(type==='Sankey'){if(!Array.isArray(input.nodes)||input.nodes.length<2||!Array.isArray(input.links)||!input.links.length)fail('CHART_SANKEY','nodes and links required');const ids=new Set(input.nodes.map(n=>String(n.id)));if(ids.size!==input.nodes.length)fail('CHART_SANKEY','node ids must be unique');const links=input.links.map((l,i)=>{const source=String(l.source),target=String(l.target),value=number(l.value,`link ${i}`);if(!ids.has(source)||!ids.has(target)||source===target||value<0)fail('CHART_SANKEY','invalid sankey link',{i});return freeze({source,target,value});});data=freeze({nodes:freeze(input.nodes.map(n=>freeze({id:String(n.id),label:String(n.label??n.id)}))),links:freeze(links)});
 }else fail('CHART_TYPE','unimplemented chart type',{type});
 return freeze({schema:'viz.core-chart.v1',type,data,semanticId:String(input.semanticId??`chart:${type}`),provenance:String(input.provenance??'user'),fingerprint:stableFingerprint({type,data})});}
export function stableFingerprint(x){const s=JSON.stringify(x);let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return`cc1-${(h>>>0).toString(16).padStart(8,'0')}`;}
